// Monta HTML do email
const d = $json;
const statusEmoji = d.status === 'sent' ? '✅' : '❌';
const statusText = d.status === 'sent' ? 'Candidatura enviada' : `Falhou: ${d.error}`;
const gaps = JSON.parse(d.requirements_gap || '[]').map(g => `<li>${g.skill} <em>(${g.severity})</em></li>`).join('');

const html = `
<h2>${statusEmoji} ${d.title} @ ${d.company}</h2>
<p><strong>Status:</strong> ${statusText}</p>
<p><strong>Score:</strong> ${d.score}/100 • <strong>Local:</strong> ${d.location} • <strong>Fonte:</strong> ${d.source}</p>
<p>${d.summary}</p>
<h3>Gaps</h3>
<ul>${gaps}</ul>
<h3>Carta enviada</h3>
<pre style="white-space:pre-wrap;font-family:Georgia,serif">${d.cover_letter || '(sem carta)'}</pre>
<p><a href="${d.url}">Ver vaga original</a></p>
`;
const subject = `${statusEmoji} ${d.title} @ ${d.company} (score ${d.score})`;
return [{ json: { subject, html, to: ($env && $env.NOTIFY_EMAIL_TO) || 'fabiokansas@gmail.com' } }];
